'use strict';
const $=id=>document.getElementById(id),STORAGE='bitterradish-li-v1';
let route=[],map,line,marks=[],seq=0,tideCache=null;
const endpoints=[['east','East Rockaway Inlet',0],['jones','Jones Inlet · inside junction',8.02],['fire','Fire Island Inlet · inside area',21.78],['smith','Smith Point Bridge',45.09],['moriches','Moriches Inlet · inside area',50.8],['shinnecockInlet','Shinnecock Inlet · inside area',64.81],['shinnecock','Shinnecock Canal · north end',67.09]];
const points=[{name:'Bellport Bay · near Smith Point',s:44.76,id:'8513388',station:'Moriches Coast Guard Station',basis:'Reported shoaling; station assignment approximate',lat:40.73583,lon:-72.87433},{name:'Narrow Bay · east of Smith Point',s:45.72,id:'8513388',station:'Moriches Coast Guard Station',basis:'Reported shoaling; station assignment approximate',lat:40.74133,lon:-72.858},{name:'Moriches Bay · inlet area',s:50.8,id:'8513388',station:'Moriches Coast Guard Station',basis:'Shoaling-prone area; precise priority point still to be verified',lat:40.779589,lon:-72.760663}];
const bridges=[{name:'Atlantic Beach Bridge',s:.54,id:'waitAtlantic',detail:'Drawbridge · restrictions and advance notice can apply'},{name:'Long Beach Bridge',s:4.44,id:'waitLong',detail:'Drawbridge · restrictions and advance notice can apply'},{name:'Smith Point Bridge',s:45.09,id:'waitSmith',detail:'Drawbridge · replacement work; verify latest navigation notices'}];
const fmt=t=>new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(t);
function eastern(date,time){let p=(date+'T'+time).split(/[-T:]/).map(Number),target=Date.UTC(p[0],p[1]-1,p[2],p[3],p[4]),t=target,f=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(let i=0;i<5;i++){let x=Object.fromEntries(f.formatToParts(t).map(y=>[y.type,y.value]));let delta=target-Date.UTC(+x.year,+x.month-1,+x.day,+x.hour,+x.minute);t+=delta;if(!delta)return t;}throw Error('This local time does not exist. Choose another departure time.');}
function pos(s){let i=route.findIndex(p=>p[2]>=s);if(i<0)i=route.length-1;if(i===0)return route[0].slice(0,2);let a=route[i-1],b=route[i],f=(s-a[2])/(b[2]-a[2]);return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f];}
function durationBetween(a,b,speed,slow){let distance=Math.abs(b-a),low=Math.min(a,b),high=Math.max(a,b),canal=Math.max(0,Math.min(high,67.09)-Math.max(low,66.39));return (distance-canal)/speed*3600000+canal/Math.min(speed,slow)*3600000;}
function eta(s,start,from,to,speed,slow,wait){let direction=Math.sign(to-from),elapsed=durationBetween(from,s,speed,slow);for(const b of bridges)if($(b.id).checked&&(b.s-from)*direction>0&&(s-b.s)*direction>=0)elapsed+=wait*60000;return start+elapsed;}
function tideAt(rows,t){if(!rows?.length||t<rows[0].t||t>rows.at(-1).t)return null;let l=0,h=rows.length-1;while(h-l>1){let m=(l+h)>>1;if(rows[m].t<=t)l=m;else h=m;}return rows[l].v+(rows[h].v-rows[l].v)*(t-rows[l].t)/(rows[h].t-rows[l].t);}
function ymd(t){return new Date(t).toISOString().slice(0,10).replaceAll('-','');}
async function loadTides(start){let begin=ymd(start-2*86400000),end=ymd(start+3*86400000),key=begin+end;if(tideCache?.key===key)return tideCache.rows;const p=new URLSearchParams({product:'predictions',application:'bitterradish',begin_date:begin,end_date:end,datum:'MLLW',station:'8513388',time_zone:'gmt',units:'english',format:'json',interval:'6'});let response=await fetch('https://api.tidesandcurrents.noaa.gov/api/prod/datagetter?'+p);if(!response.ok)throw Error('NOAA tide predictions unavailable');let j=await response.json();if(!j.predictions)throw Error(j.error?.message||'NOAA tide predictions unavailable');let rows=j.predictions.map(x=>({t:Date.parse(x.t.replace(' ','T')+'Z'),v:Number(x.v)})).filter(x=>Number.isFinite(x.t)&&Number.isFinite(x.v));if(rows.length<2)throw Error('NOAA returned insufficient predictions');tideCache={key,rows};return rows;}
function save(){let x={};document.querySelectorAll('#form input,#form select').forEach(e=>x[e.id]=e.type==='checkbox'?e.checked:e.value);try{localStorage.setItem(STORAGE,JSON.stringify(x));}catch(e){}}
function restore(){try{let x=JSON.parse(localStorage.getItem(STORAGE)||'{}');document.querySelectorAll('#form input,#form select').forEach(e=>{if(x[e.id]!==undefined){if(e.type==='checkbox')e.checked=x[e.id];else e.value=x[e.id];}})}catch(e){}}
function dateValue(t){let p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(t).map(x=>[x.type,x.value]));return [p.year+'-'+p.month+'-'+p.day,p.hour+':'+p.minute];}
function setDeparture(t){let [d,h]=dateValue(t);$('date').value=d;$('time').value=h;save();update();}
function draw(a,b,selected){if(!map)return;if(line)map.removeLayer(line);marks.forEach(m=>map.removeLayer(m));marks=[];let low=Math.min(a,b),high=Math.max(a,b),coords=[pos(low),...route.filter(x=>x[2]>low&&x[2]<high).map(x=>x.slice(0,2)),pos(high)];line=L.polyline(coords,{color:'#167c81',weight:5}).addTo(map);for(let x of selected){let p=pos(x.s),m=L.circleMarker(p,{radius:7,color:'#fff',weight:2,fillColor:'#db862c',fillOpacity:1}).addTo(map).bindTooltip(x.name);marks.push(m);}map.fitBounds(line.getBounds().pad(.1));}
async function update(){if(!$('form').checkValidity()||!route.length)return;save();let current=++seq;let a=endpoints.find(x=>x[0]===$('start').value),b=endpoints.find(x=>x[0]===$('finish').value);if(!a||!b||a===b){$('status').textContent='Choose different start and finish points.';return;}let start;try{start=eastern($('date').value,$('time').value)}catch(e){$('status').textContent=e.message;return;}let speed=+$('speed').value,slow=+$('slow').value,wait=+$('wait').value,dir=Math.sign(b[2]-a[2]);let included=points.filter(x=>(x.s-a[2])*dir>=0&&(b[2]-x.s)*dir>=0).sort((x,y)=>dir*(x.s-y.s)),usedBridges=bridges.filter(x=>(x.s-a[2])*dir>=0&&(b[2]-x.s)*dir>=0).sort((x,y)=>dir*(x.s-y.s));draw(a[2],b[2],included);let end=eta(b[2],start,a[2],b[2],speed,slow,wait);$('summary').innerHTML=`<p><b>${a[1]} → ${b[1]}</b><br>${Math.abs(b[2]-a[2]).toFixed(1)} nm · Depart ${fmt(start)} · Arrive approximately ${fmt(end)}<br>Estimated travel time ${Math.floor((end-start)/3600000)}h ${Math.round((end-start)%3600000/60000)}m</p>`;$('bridgeList').innerHTML=usedBridges.length?'<ul>'+usedBridges.map(x=>`<li><b>${x.name}</b> · ${x.detail} · ${$(x.id).checked?wait+' min manual allowance':'no wait included'}</li>`).join('')+'</ul><p>Other bridges and clearances have not been fully inventoried.</p>':'No inventoried bridges in this selected section. Other bridges and clearances have not been fully inventoried.';$('status').textContent='Loading NOAA tide predictions…';$('tides').innerHTML='';$('choices').innerHTML='';if(!included.length){$('status').textContent='No researched priority tide locations in this section; this does not mean there are no shallow areas.';return;}
 try{let rows=await loadTides(start);if(current!==seq)return;function evaluate(t){let values=included.map(p=>{let time=eta(p.s,t,a[2],b[2],speed,slow,wait);return {...p,time,tide:tideAt(rows,time)}});return {start:t,values,lowest:values.every(v=>v.tide!==null)?Math.min(...values.map(v=>v.tide)):null};}let chosen=evaluate(start);$('tides').innerHTML=chosen.values.map(x=>`<tr><td>${x.name}</td><td>${fmt(x.time)}</td><td class="li-tide">${x.tide===null?'Unavailable':x.tide.toFixed(2)+' ft MLLW'}</td><td>${x.station} · ${x.basis}</td></tr>`).join('');let options=[];for(let i=-20;i<=20;i++)options.push(evaluate(start+i*1800000));options=options.filter(x=>x.lowest!==null);if(options.length){let best=options.reduce((a,b)=>b.lowest>a.lowest?b:a),worst=options.reduce((a,b)=>b.lowest<a.lowest?b:a);$('choices').innerHTML=[['Highest minimum tide',best],['Lowest minimum tide',worst]].map(([label,x],i)=>`<div><b>${label}</b><p>${fmt(x.start)}<br>${x.lowest.toFixed(2)} ft MLLW at limiting station</p><button id="pick${i}">Use departure</button></div>`).join('');$('pick0').onclick=()=>setDeparture(best.start);$('pick1').onclick=()=>setDeparture(worst.start);}$('status').textContent='Estimates use NOAA station predictions and provisional arrival times.';}catch(e){if(current!==seq)return;$('status').textContent='Tide predictions unavailable: '+e.message+'. No zero tide was substituted.';$('tides').innerHTML='<tr><td colspan="4">NOAA forecast unavailable. Check connection, dates and station coverage.</td></tr>';}}
async function init(){let response=await fetch('li-route.json?v=20261103');if(!response.ok)throw Error('Route file unavailable');route=await response.json();for(const id of ['start','finish'])$(id).innerHTML=endpoints.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');$('finish').value='shinnecock';$('date').value=dateValue(Date.now())[0];restore();if(window.L){map=L.map('map').setView([40.72,-73.1],9);L.tileLayer.wms('https://gis.charttools.noaa.gov/arcgis/rest/services/MCS/NOAAChartDisplay/MapServer/exts/MaritimeChartService/WMSServer',{layers:'0,1,2,3,4,5,6,7',format:'image/png',version:'1.1.1',attribution:'NOAA nautical chart'}).addTo(map);}$('swap').onclick=()=>{let x=$('start').value;$('start').value=$('finish').value;$('finish').value=x;update();};let timer;$('form').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(update,250)});$('form').addEventListener('change',()=>{clearTimeout(timer);update()});update();}
init().catch(e=>{$('status').textContent='Could not initialize planner: '+e.message;});
